INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1039995, 125210, 16648, '<td valign="top">Cool idea to rotate it. Nice illusion.<br/>Try this to get more ''pop'' from your photo by removing the haze - USM 40%, radius 60, t-hold 1.</td>', 'Cool idea to rotate it. Nice illusion.Try this to get more ''pop'' from your photo by removing the haze - USM 40%, radius 60, t-hold 1.', '2004-12-01 02:50:11.000000', NULL, 1),
(1039996, 124303, 20214, '<td valign="top">a photograph which contains exactly seven of the main subject.</td>', 'a photograph which contains exactly seven of the main subject.', '2004-12-01 02:50:14.000000', NULL, 1),
(1039998, 124061, 20925, '<td valign="top">cool shot.  feels post-apocalyptic.</td>', 'cool shot.  feels post-apocalyptic.', '2004-12-01 02:50:35.000000', NULL, 1),
(1039999, 125175, 29849, '<td valign="top">The lighting and tone of this photo are great - you''ve really captured the groggy-eyed feeling.  The missing light in the upper right helps draw the eye from the front aisle triangle to the inverted triangle created by the darkness on the wall.  Nicely done.</td>', 'The lighting and tone of this photo are great - you''ve really captured the groggy-eyed feeling.  The missing light in the upper right helps draw the eye from the front aisle triangle to the inverted triangle created by the darkness on the wall.  Nicely done.', '2004-12-01 02:50:36.000000', NULL, 1),
(1040000, 124778, 20214, '<td valign="top">WOW, great shot! 10</td>', 'WOW, great shot! 10', '2004-12-01 02:50:39.000000', NULL, 1),
(1040001, 124896, 24674, '<td valign="top">great shot. best so far</td>', 'great shot. best so far', '2004-12-01 02:50:53.000000', NULL, 1),
