(1044911, 124465, 25095, '<td valign="top">nice job.  Looks like a ribbon is on its way.  Very creative.</td>', 'nice job.  Looks like a ribbon is on its way.  Very creative.', '2004-12-03 15:42:58.000000', NULL, 1),
(1044917, 125137, 27845, '<td valign="top">Good question! It''s pretty hard to count them! I like that. The colours are nice, I''d have prefered softer shadows. Good idea, well executed. 8.</td>', 'Good question! It''s pretty hard to count them! I like that. The colours are nice, I''d have prefered softer shadows. Good idea, well executed. 8.', '2004-12-03 15:44:56.000000', NULL, 1),
(1044921, 124081, 27524, '<td valign="top">Very interesting capture...good idea angle and macro.</td>', 'Very interesting capture...good idea angle and macro.', '2004-12-03 15:48:39.000000', NULL, 1),
