(1046359, 125111, 25355, '<td valign="top">There are more than seven.</td>', 'There are more than seven.', '2004-12-04 19:29:52.000000', NULL, 1),
(1046361, 125031, 25355, '<td valign="top">I don''t see seven objects the same.</td>', 'I don''t see seven objects the same.', '2004-12-04 19:30:44.000000', NULL, 1),
(1046364, 123983, 25355, '<td valign="top">Image too small and only one object (reflected).</td>', 'Image too small and only one object (reflected).', '2004-12-04 19:32:25.000000', NULL, 1),
(1046368, 124246, 9576, '<td valign="top">Remiend me of my shooting days, now I shoot my camera ;-) ok groub for 300 meters</td>', 'Remiend me of my shooting days, now I shoot my camera ;-) ok groub for 300 meters', '2004-12-04 19:34:43.000000', NULL, 1),
