(1046455, 125077, 26756, '<td valign="top">Not wild about the light fall off on the left edges but the subject choice and how you set this up was extremely creative.</td>', 'Not wild about the light fall off on the left edges but the subject choice and how you set this up was extremely creative.', '2004-12-04 21:03:04.000000', NULL, 1),
(1046458, 124962, 26756, '<td valign="top">Great subject.  Interesting to show two different ages of a city, with the more modern building in the background.</td>', 'Great subject.  Interesting to show two different ages of a city, with the more modern building in the background.', '2004-12-04 21:05:46.000000', NULL, 1),
(1046461, 124935, 26756, '<td valign="top">Nice capture.  I like the lighting and tonality in the reeds, and your subject is very unique.</td>', 'Nice capture.  I like the lighting and tonality in the reeds, and your subject is very unique.', '2004-12-04 21:08:58.000000', NULL, 1),
(1046462, 124764, 26756, '<td valign="top">Technically very well done, an interesting subject choice and very creative.</td>', 'Technically very well done, an interesting subject choice and very creative.', '2004-12-04 21:10:09.000000', NULL, 1),
