(1048965, 123933, 30342, '<td valign="top">Great colors and framing!</td>', 'Great colors and framing!', '2004-12-06 16:16:17.000000', NULL, 1),
(1048966, 125177, 30342, '<td valign="top">Very professional looking.</td>', 'Very professional looking.', '2004-12-06 16:16:28.000000', NULL, 1),
